  1	/* ============================================================
  2	   api-client.js — API Client module
  3	   Section 1 of the MCP Server Dashboard SPA
  4	   ============================================================ */
  5	
  6	var API = (function () {
  7	  async function request(method, path, body) {
  8	    var opts = {
  9	      method: method,
 10	      headers: {},
 11	    };
 12	    if (body !== undefined) {
 13	      opts.headers['Content-Type'] = 'application/json';
 14	      opts.body = JSON.stringify(body);
 15	    }
 16	    var res = await fetch('/api' + path, opts);
 17	    if (!res.ok) {
 18	      var errData = null;
 19	      try { errData = await res.json(); } catch (_) {}
 20	      var errMsg = (errData && errData.error && errData.error.message) || ('HTTP ' + res.status);
 21	      var errCode = (errData && errData.error && errData.error.code) || 'ERROR';
 22	      throw { code: errCode, message: errMsg };
 23	    }
 24	    if (res.status === 204) return null;
 25	    return res.json();
 26	  }
 27	
 28	  /**
 29	   * Serialize *params* as a URL query string.
 30	   *
 31	   * Keys whose value is `undefined` or an empty string (`''`) are silently
 32	   * omitted from the output.  This is intentional: callers use `undefined` as
 33	   * a "no filter" sentinel (e.g. `{ wp: wpId }` where `wpId` may be
 34	   * `undefined`), and the omission prevents `?wp=undefined` from reaching
 35	   * the server.
 36	   *
 37	   * @param {Record<string, any>|null|undefined} params - Key/value pairs to encode.
 38	   * @returns {string} A `?key=value&…` string, or `''` when no params survive
 39	   *   the filter.
 40	   */
 41	  function buildQueryString(params) {
 42	    if (!params) return '';
 43	    var parts = Object.keys(params)
 44	      .filter(function (k) { return params[k] !== undefined && params[k] !== ''; })
 45	      .map(function (k) { return encodeURIComponent(k) + '=' + encodeURIComponent(params[k]); });
 46	    return parts.length ? '?' + parts.join('&') : '';
 47	  }
 48	
 49	  return {
 50	    getProjects: function (params) {
 51	      return request('GET', '/projects' + buildQueryString(params));
 52	    },
 53	    getProject:               function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug)); },
 54	    getWorkPackages:          function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/work-packages'); },
 55	    getWorkPackage:           function (repo, slug, wpId)   { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/work-packages/' + encodeURIComponent(wpId)); },
 56	    deleteProject:            function (repo, slug)         { return request('DELETE', '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug)); },
 57	    archiveProject:           function (repo, slug)         { return request('POST',   '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/archive'); },
 58	    unarchiveProject:         function (repo, slug)         { return request('POST',   '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/unarchive'); },
 59	    getConfig:                function ()             { return request('GET',    '/config'); },
 60	    updateConfig:             function (data)         { return request('PUT',    '/config', data); },
 61	    getInsights:              function ()             { return request('GET',    '/insights'); },
 62	    getServerInfo:            function ()             { return request('GET',    '/server-info'); },
 63	    getPlanDocument:          function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/plan'); },
 64	    getSynthesisDocument:     function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/synthesis'); },
 65	    analyzeProjectReset:      function (repo, slug)         { return request('POST',   '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/reset', { dry_run: true }); },
 66	    applyProjectReset:        function (repo, slug, decisions) { return request('POST', '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/reset', { dry_run: false, decisions: decisions }); },
 67	    getProjectHealth:         function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/health'); },
 68	    getWorkPackageOverview:   function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/work-packages/overview'); },
 69	    renameProject:            function (repo, slug, title)  { return request('PATCH',  '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug), { title: title }); },
 70	    renameSlug:               function (repo, slug, newSlug) { return request('PATCH',  '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug), { slug: newSlug }); },
 71	    markProjectComplete:      function (repo, slug)         { return request('POST',   '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/complete'); },
 72	    getRunLogs:               function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/runs'); },
 73	    getRunLogEntries:         function (repo, slug, filename, afterLine) {
 74	      var qs = (afterLine !== undefined && afterLine !== null) ? ('?after=' + encodeURIComponent(afterLine)) : '';
 75	      return request('GET', '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/runs/' + encodeURIComponent(filename) + qs);
 76	    },
 77	    getRunMetadata:           function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/run-metadata'); },
 78	    getDialogues: function (repo, slug, wpId) {
 79	      return request('GET', '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/dialogues' + buildQueryString({ wp: wpId }));
 80	    },
 81	    getDialogueContent: function (repo, slug, filename) {
 82	      return request('GET', '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/dialogues/' + encodeURIComponent(filename))
 83	        .then(function (data) { return data.content; });
 84	    },
 85	    getChunks: function (repo, slug, wpId) {
 86	      return request('GET', '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/chunks' + buildQueryString({ wp: wpId }));
 87	    },
 88	    getChunkRendered: function (repo, slug, filename) {
 89	      return request('GET', '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/chunks/' + encodeURIComponent(filename) + '/rendered')
 90	        .then(function (data) { return data.content; });
 91	    },
 92	
 93	    // -- Orchestrator --------------------------------------------------
 94	    orchestratorStart: function (planPath, dryRun, resumeThreadId) {
 95	      var body = { planPath: planPath, dryRun: dryRun };
 96	      if (resumeThreadId !== undefined) body.resumeThreadId = resumeThreadId;
 97	      return request('POST', '/orchestrator/start', body);
 98	    },
 99	    orchestratorGetQueue:    function ()                 { return request('GET',    '/orchestrator/queue'); },
100	    orchestratorGetRunStatus: function (slug)            { return request('GET',    '/orchestrator/run-status/' + encodeURIComponent(slug)); },

  1	// @vitest-environment jsdom
  2	
  3	/**
  4	 * Tests for gui/public/api-client.js — run log, server-info, orchestrator,
  5	 * and knowledge methods.
  6	 *
  7	 * Uses jsdom + vm.runInThisContext to load the browser-side script, then mocks
  8	 * globalThis.fetch to assert the URLs and options that API methods produce.
  9	 */
 10	
 11	import { describe, it, expect, beforeAll, vi } from 'vitest';
 12	import { readFileSync } from 'node:fs';
 13	import { join } from 'node:path';
 14	import vm from 'node:vm';
 15	
 16	// ---------------------------------------------------------------------------
 17	// Load client script
 18	// ---------------------------------------------------------------------------
 19	
 20	const publicDir = join(__dirname, '../../gui/public');
 21	const apiClientJs = readFileSync(join(publicDir, 'api-client.js'), 'utf-8');
 22	
 23	// Execute once so the API var is available globally (as in a browser)
 24	beforeAll(() => {
 25	  vm.runInThisContext(apiClientJs);
 26	});
 27	
 28	// Declare globalThis.API for TypeScript
 29	declare global {
 30	  // eslint-disable-next-line no-var
 31	  var API: {
 32	    getRunLogs: (repo: string, slug: string) => Promise<unknown>;
 33	    getRunLogEntries: (repo: string, slug: string, filename: string, afterLine?: number) => Promise<unknown>;
 34	    [key: string]: (...args: unknown[]) => Promise<unknown>;
 35	  };
 36	}
 37	
 38	// ---------------------------------------------------------------------------
 39	// Helpers
 40	// ---------------------------------------------------------------------------
 41	
 42	/**
 43	 * Installs a mock `fetch` on globalThis that resolves with the provided JSON
 44	 * body and records the most-recent call arguments.
 45	 */
 46	function mockFetch(responseBody: unknown = null, status = 200) {
 47	  const calls: { url: string; opts: RequestInit }[] = [];
 48	  const mockFn = vi.fn(async (url: string, opts: RequestInit) => {
 49	    calls.push({ url, opts });
 50	    return {
 51	      ok: status >= 200 && status < 300,
 52	      status,
 53	      json: async () => responseBody,
 54	    };
 55	  });
 56	  // jsdom exposes globalThis.fetch — replace it for the duration of the test
 57	  (globalThis as unknown as Record<string, unknown>)['fetch'] = mockFn;
 58	  return calls;
 59	}
 60	
 61	// ---------------------------------------------------------------------------
 62	// getRunLogs
 63	// ---------------------------------------------------------------------------
 64	
 65	describe('API.getRunLogs', () => {
 66	  it('calls GET /api/projects/{repo}/{slug}/runs', async () => {
 67	    const calls = mockFetch([]);
 68	
 69	    await globalThis.API.getRunLogs('my-repo', 'my-slug');
 70	
 71	    expect(calls).toHaveLength(1);
 72	    expect(calls[0]!.url).toBe('/api/projects/my-repo/my-slug/runs');
 73	    expect(calls[0]!.opts.method).toBe('GET');
 74	  });
 75	
 76	  it('encodes both repo and slug via encodeURIComponent', async () => {
 77	    const calls = mockFetch([]);
 78	
 79	    await globalThis.API.getRunLogs('my repo', 'slug with spaces');
 80	
 81	    expect(calls[0]!.url).toBe('/api/projects/my%20repo/slug%20with%20spaces/runs');
 82	  });
 83	});
 84	
 85	// ---------------------------------------------------------------------------
 86	// getRunLogEntries
 87	// ---------------------------------------------------------------------------
 88	
 89	describe('API.getRunLogEntries', () => {
 90	  it('calls GET /api/projects/{repo}/{slug}/runs/{filename} without ?after when afterLine is omitted', async () => {
 91	    const calls = mockFetch({ entries: [], totalLines: 0 });
 92	
 93	    await globalThis.API.getRunLogEntries('my-repo', 'my-slug', 'file.jsonl');
 94	
 95	    expect(calls).toHaveLength(1);
 96	    expect(calls[0]!.url).toBe('/api/projects/my-repo/my-slug/runs/file.jsonl');
 97	    expect(calls[0]!.url).not.toContain('?after=');
 98	  });
 99	
100	  it('appends ?after={afterLine} when afterLine is provided', async () => {

101	    const calls = mockFetch({ entries: [], totalLines: 10 });
102	
103	    await globalThis.API.getRunLogEntries('my-repo', 'my-slug', '20260225T113355-my-slug.jsonl', 5);
104	
105	    expect(calls).toHaveLength(1);
106	    expect(calls[0]!.url).toBe('/api/projects/my-repo/my-slug/runs/20260225T113355-my-slug.jsonl?after=5');
107	  });
108	
109	  it('encodes the filename via encodeURIComponent', async () => {
110	    const calls = mockFetch({ entries: [], totalLines: 0 });
111	
112	    // A filename with a space — unlikely in practice but must be safe
113	    await globalThis.API.getRunLogEntries('my-repo', 'my-slug', 'file name.jsonl');
114	
115	    expect(calls[0]!.url).toBe('/api/projects/my-repo/my-slug/runs/file%20name.jsonl');
116	  });
117	
118	  it('encodes both repo and slug via encodeURIComponent', async () => {
